MAIN_PROGRESS_ID = 'crits' MAIN_PROGRESS_SERIES = 'battlesSeries' MAIN_PROGRESS_TOP_BY_EXP = 'topByExp'
def onInit(eventType, eventData, quest, processor): for event in events.iterkeys(): processor.subscribe(event, quest) return True
def onFinishBattle(eventType, eventData, quest, processor): questProgress = quest_progress.BaseQuestProgress(quest.config, processor.getQuestProgress(quest.progressID))
brfilter = filter.BattleResultsFilter(eventData)
topByExp = eventData['avatarResults']['misc']['max']['xp'] topByExpRes = topByExp <= questProgress.getProgress(MAIN_PROGRESS_TOP_BY_EXP).getParam("desiredPosition") mainCondition = brfilter.sumCrits(criticalType=questProgress.getProgress(MAIN_PROGRESS_CRITS).getParam("critTypes"))
if topByExpRes: questProgress.increaseSeriesUntilComplete(MAIN_PROGRESS_SERIES, MAIN_PROGRESS_ID, mainCondition) eventData['results'].update(processor.checkComplete(questProgress, quest.progressID)) processor.setQuestProgress(quest.progressID, questProgress.save())
events = { QUEST_EVENT_TYPE.INIT: onInit, QUEST_EVENT_TYPE.FINISH_BATTLE: onFinishBattle, }
def quest(eventType, eventData, quest, processor): LOG('QUEST EVENT:', eventType, quest.id) return events.get(eventType, lambda *args: False)(eventType, eventData, quest, processor)
